package org.example.model;

import jakarta.persistence.*;
import lombok.*;
import org.hibernate.annotations.CreationTimestamp;
import java.time.LocalDateTime;

@Entity
@Table(name = "users")
@Getter @Setter
@NoArgsConstructor @AllArgsConstructor
@Builder
@ToString @EqualsAndHashCode
public class User {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @CreationTimestamp
    @Column(updatable = false)
    private LocalDateTime registration;

    @Column(nullable = false, unique = true, updatable = false)
    private String nick;

    @Column(columnDefinition = "TEXT")
    private String info;
}

@Entity
@Table(name = "problems")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
@ToString @EqualsAndHashCode
public class Problem {

    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @CreationTimestamp @Column(updatable = false)
    private LocalDateTime publication;

    @ManyToOne(optional = false)
    @JoinColumn(name = "questioner_id")
    private User questioner;

    @Column(nullable = false, length = 200)
    private String title;

    @Column(nullable = false, columnDefinition = "TEXT")
    private String question;

    @OneToMany(mappedBy = "problem")
    @ToString.Exclude
    @EqualsAndHashCode.Exclude
    @Builder.Default
    private List<Idea> ideas = new ArrayList<>();
}

@Entity
@Table(name = "ideas")
@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder
@ToString @EqualsAndHashCode
public class Idea {

    @Id @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @CreationTimestamp @Column(updatable = false)
    private LocalDateTime publication;

    @ManyToOne(optional = false)
    @JoinColumn(name = "originator_id")
    private User originator;

    @ManyToOne(optional = false)
    @JoinColumn(name = "problem_id")
    @ToString.Exclude
    @EqualsAndHashCode.Exclude
    private Problem problem;

    @Column(nullable = false, columnDefinition = "TEXT")
    private String answer;
}

package org.example.persistence;

import org.example.model.*;
import org.hibernate.Session;
import org.hibernate.SessionFactory;
import org.hibernate.cfg.Configuration;

public class HibernateSessionFactory {

    private static final SessionFactory sessionFactory;

    static {
        sessionFactory = new Configuration()
                .addAnnotatedClass(User.class)
                .addAnnotatedClass(Problem.class)
                .addAnnotatedClass(Idea.class)
                .buildSessionFactory();

        Runtime.getRuntime().addShutdownHook(new Thread(sessionFactory::close));
    }

    public static Session getNewSession() {
        return sessionFactory.openSession();
    }
}

public class App_1 {
    public static void main(String[] args) {

        User u1 = User.builder().nick("anna").info("Lubi algorytmy").build();
        User u2 = User.builder().nick("bartek").info("Backend").build();
        User u3 = User.builder().nick("celina").info("Testy").build();

        Problem p1 = Problem.builder().questioner(u1)
                .title("Jak szybko sortować?").question("Jaki algorytm dla 1 mln liczb?").build();
        Problem p2 = Problem.builder().questioner(u2)
                .title("Jak uczyć się Springa?").question("Od czego zacząć?").build();

        Idea i1 = Idea.builder().originator(u2).problem(p1).answer("Quicksort / sort() z biblioteki").build();
        Idea i2 = Idea.builder().originator(u3).problem(p1).answer("Merge sort – stabilny").build();
        Idea i3 = Idea.builder().originator(u1).problem(p2).answer("Zacząć od Spring Boot").build();

        System.out.println(u1);   // toString z Lomboka

        try (Session session = HibernateSessionFactory.getNewSession()) {
            Transaction tx = session.beginTransaction();
            session.persist(u1); session.persist(u2); session.persist(u3);
            session.persist(p1); session.persist(p2);
            session.persist(i1); session.persist(i2); session.persist(i3);
            tx.commit();
        }
    }
}

// App_2 – wszyscy użytkownicy
try (Session session = HibernateSessionFactory.getNewSession()) {
    List<User> users = session
            .createSelectionQuery("from User", User.class)
            .getResultList();
    users.forEach(System.out::println);
}

// App_3 – problemy z pomysłami i autorami, wszystko w jednej sesji
try (Session session = HibernateSessionFactory.getNewSession()) {
    List<Problem> problems = session
            .createSelectionQuery("from Problem", Problem.class)
            .getResultList();
    for (Problem p : problems) {
        System.out.println(p.getTitle() + " – " + p.getQuestioner().getNick());
        for (Idea i : p.getIdeas())                       // leniwe ładowanie – sesja jeszcze otwarta
            System.out.println("  • " + i.getAnswer() + " – " + i.getOriginator().getNick());
    }
}

