public class App_5 {
    public static void main(String[] args) throws IOException {
        List<User> users;
        try (Session session = HibernateSessionFactory.getNewSession()) {
            users = session.createSelectionQuery("from User", User.class).getResultList();
        }

        ClassLoaderTemplateResolver resolver = new ClassLoaderTemplateResolver();
        resolver.setTemplateMode(TemplateMode.HTML);
        resolver.setPrefix("/");
        resolver.setSuffix(".html");

        TemplateEngine engine = new TemplateEngine();
        engine.setTemplateResolver(resolver);

        Context context = new Context();
        context.setVariable("users", users);

        String html = engine.process("users", context);
        Files.writeString(Path.of("users-output.html"), html);
    }
}

